mapper.select:
SELECT * FROM( SELECT CPI.*, LCW.WITHDRAW_NUMBER, LCW.REPORT_NAME, CON.CONTRACT_NAME, CON.CONTRACT_NUMBER, FLOW.DUE_AMOUNT, FLOW.SURPLUS_AMOUNT, FLOW.PRINCIPAL, FLOW.INTEREST, FLOW.DUE_DATE FROM CT_LON_CONTRACT_PLEDGE_INFO CPI JOIN CT_LON_CONTRACT_PLEDGE CP ON CPI.PLEDGE_ID=CP.PLEDGE_ID JOIN LON_CONTRACT_WITHDRAW LCW ON LCW.WITHDRAW_ID=CPI.WITHDRAW_ID JOIN CON_CONTRACT CON ON CON.CONTRACT_ID=CP.PLEDGE_DOC_ID AND CP.PLEDGE_DOC_CATEGORY='CON_CONTRACT' JOIN ( SELECT CCC.CONTRACT_ID, CCC.TIMES, SUM(CCC.DUE_AMOUNT) DUE_AMOUNT, SUM(CCC.PRINCIPAL) PRINCIPAL, SUM(CCC.INTEREST) INTEREST, MIN(CCC.DUE_DATE) DUE_DATE, nvl(SUM(CCC.DUE_AMOUNT),0) -nvl(SUM(CCC.RECEIVED_AMOUNT),0) SURPLUS_AMOUNT FROM CON_CONTRACT_CASHFLOW CCC WHERE CCC.CF_STATUS='RELEASE' AND CCC.CF_DIRECTION='INFLOW' AND CCC.CF_ITEM=1 GROUP BY CCC.CONTRACT_ID, CCC.TIMES) FLOW ON FLOW.CONTRACT_ID= CON.CONTRACT_ID AND FLOW.TIMES=CPI.PLEDGE_TIMES WHERE CON.DATA_CLASS='NORMAL' UNION SELECT CPI.*, LCW.WITHDRAW_NUMBER, LCW.REPORT_NAME, CON.CONTRACT_NAME, CON.CONTRACT_NUMBER, FLOW.DUE_AMOUNT, FLOW.SURPLUS_AMOUNT, FLOW.PRINCIPAL, FLOW.INTEREST, FLOW.DUE_DATE FROM CT_LON_CONTRACT_PLEDGE_INFO CPI JOIN CT_LON_CONTRACT_PLEDGE CP ON CPI.PLEDGE_ID=CP.PLEDGE_ID JOIN LON_CONTRACT_WITHDRAW LCW ON LCW.WITHDRAW_ID=CPI.WITHDRAW_ID JOIN FCT_CONTRACT CON ON CON.CONTRACT_ID=CP.PLEDGE_DOC_ID AND CP.PLEDGE_DOC_CATEGORY='FCT_CONTRACT' JOIN ( SELECT CCC.CONTRACT_ID, CCC.TIMES, SUM(CCC.DUE_AMOUNT) DUE_AMOUNT, SUM((case when CCC.CF_ITEM = 54 then CCC.DUE_AMOUNT else 0 end)) PRINCIPAL, SUM((case when CCC.CF_ITEM = 55 then CCC.DUE_AMOUNT else 0 end)) INTEREST, MIN(CCC.DUE_DATE) DUE_DATE, nvl(SUM(CCC.DUE_AMOUNT),0) -nvl(SUM(CCC.RECEIVED_AMOUNT),0) SURPLUS_AMOUNT FROM FCT_QUOTATION_CASHFLOW CCC WHERE CCC.CF_STATUS='RELEASE' AND CCC.CF_DIRECTION='INFLOW' AND CCC.CF_ITEM IN(54,55) GROUP BY CCC.CONTRACT_ID, CCC.TIMES) FLOW ON FLOW.CONTRACT_ID= CON.CONTRACT_ID AND FLOW.TIMES=CPI.PLEDGE_TIMES WHERE CON.DATA_CLASS='NORMAL' ) TEM WHERE 1=1
AND TEM.PLEDGE_ID = #{pledgeId}
ORDER BY TEM.WITHDRAW_ID,TEM.PLEDGE_TIMES
